#!/usr/bin/env bash
# Work QP4 (X285-X289): the Permitted cohort (BSE inline XBRL financials). Run from the repo root on the live machine
# with the QP4 code merged (parser 0.10.9), while no other writer holds data/market.duckdb. Quarantine ids are
# deterministic (snapshot 2026-11-18 14:40).
set -euo pipefail
PY="${PY:-python}"
D="${D:-data}"
F="$PY -m financials --data-dir $D"

# --- 1. Parser 0.10.9 (X285-X287): re-parse every results filing with an open PARSE / IDENTITY / PERIOD finding,
#        then promote. Offline over both BSE runner ledgers (1,186 distinct inline results files): exactly the 6 INVALID_XBRL files
#        change, every other file reads byte-identically. Expected:
#        - promoted, INVALID_XBRL closed FIXED_BY_RULE: 539469 PANORAMA Q3 FY26 consolidated (X285),
#          519397 SHINDL Q2 FY26 standalone + consolidated (X285), 538668 MIIL Q2 FY26 consolidated (X287);
#        - 538668 MIIL Q1 FY26 'IFOtherthan' standalone + consolidated (X286) now parse and are the OtherThanBank
#          template: UNKNOWN_TAXONOMY, which rule X89 closes against the Ind AS copies of 22-Sep-2025 for the same
#          quarter; their stale INVALID_XBRL findings are closed in step 2.
#        If a 0.10.9 staging batch exists from an earlier build, delete it first.
$F restage --category RESULTS_XBRL
$F promote

# --- 2. The two 'IFOtherthan' files: once they parse (an UNKNOWN_TAXONOMY finding exists for the filing), the
#        INVALID_XBRL finding of 0.10.8 is stale. Closed only if so.
has_taxonomy_finding() {
  "$PY" - "$D" "$1" <<'PY'
import sys

import duckdb

con = duckdb.connect(f"{sys.argv[1]}/market.duckdb", read_only=True)
n = con.execute(
    "SELECT count(*) FROM quarantine_queue WHERE filing_id = ? AND reason_code = 'UNKNOWN_TAXONOMY'", [sys.argv[2]]
).fetchone()[0]
print(n)
PY
}
STALE_NOTE='QP4 [X286]: parser 0.10.9 reads the file (rule IXBRL6_TR_END_OMITTED); it is the OtherThanBank (non-Ind AS) template of 538668 Q1 FY26, now UNKNOWN_TAXONOMY (rule X89 closes that against the Ind AS filing of 22-Sep-2025 for the same quarter). The INVALID_XBRL of 0.10.8 is stale.'
if [ "$(has_taxonomy_finding fil_5eb455419f00b456aa018860)" -gt 0 ]; then
  $F quarantine resolve --id q_72285db3e7d84dc58356a5b4 --action ACCEPT --note "$STALE_NOTE"
fi
if [ "$(has_taxonomy_finding fil_adfee0bf7f54ec18fb1fba19)" -gt 0 ]; then
  $F quarantine resolve --id q_62091dba93ded108e7292c89 --action ACCEPT --note "$STALE_NOTE"
fi

# --- 3. ISIN_SYMBOL_CONFLICT (X288): Vadilal Enterprises Q3 FY26 (BSE 519152, filed 10-Feb-2026) states ISIN
#        INE593D01018 (not on record; its own is INE693D01018, one digit apart) and Symbol VADILALIND (Vadilal
#        Industries, the group company). ScripCode 519152 and the company name 'VADILAL ENTERPRISES LIMITED' are
#        Vadilal Enterprises', as in its six other BSE results files (Symbol NOTLISTED, ISIN INE693D01018).
#        The OVERRIDE re-promotes the filing at once.
$F quarantine resolve --id q_9f997f099d0611aa371d494a --action OVERRIDE --note 'QP4 [X288]: the filing is Vadilal Enterprises (VADILENT, BSE 519152): filed ScripCode 519152 and company name VADILAL ENTERPRISES LIMITED; the stated ISIN INE593D01018 is a one-digit slip of INE693D01018 and the Symbol VADILALIND is the group company Vadilal Industries; its six other BSE results files state NOTLISTED / INE693D01018.' --payload-json '{"field": "security_id", "value": "sec_37bfc25ec8bd65892f337e21"}'

# --- 4. YTD_QUARTER_MISMATCH on the Permitted cohort (80 findings, 20 entities): 47 ACCEPTed under the decision A
#        precedent, each with its evidence (PDF-checked against the companies' signed Q2 FY27 statements, vaulted as
#        BSE attachments, AttachLive URLs; or XBRL evidence); 33 stay open (docs/references.md X289).
R() { $F quarantine resolve --id "$1" --action ACCEPT --note "$2"; }
